public static String appx(String word1, String word2) {
    int count = 0;

    // Count common letters and sum lengths of words
    for (int i = 0; i < Math.min(word1.length(), word2.length()); i++) {
        if (word1.charAt(i) == word2.charAt(i)) {
            count++;
        }
    }

    // Calculate approximate value as a reduced fraction
    int denominator = word1.length() + word2.length();
    int numerator = count * 2;

    // Simplify fraction
    for (int i = 2; i <= Math.min(numerator, denominator); i++) {
        while (numerator % i == 0 && denominator % i == 0) {
            numerator /= i;
            denominator /= i;
        }
    }

    // Format and return the approximate value as a reduced fraction
    return String.format("appx(%s, %s) = %d/%d", word1, word2, numerator, denominator);
}
