public class Solution {

    public boolean canArrange(int[] arr, int k) {
        Arrays.sort(arr);
        int sum = 0;
        for (int i = 0; i < arr.length; i++) {
            sum += arr[i];
        }
        if (sum % k != 0) {
            return false;
        }
        for (int i = 0; i < arr.length; i += 2) {
            if (arr[i] % k != 0) {
                return false;
            }
        }
        int len = arr.length / 2;
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j < len; j++) {
                if ((arr[j] - arr[i]) % k == 0) {
                    return false;
                }
            }
        }
        return true;
    }

