private void helper(List<String> list, String s, int index) {
    if (index == s.length()) {
        list.remove(list.size() - 1);
        return;
    }

    String sub = s.substring(index, index + 1);
    list.add(sub);
    helper(list, s, index + 1);

    list.remove(list.size() - 1);
    if (list.size() == 0) {
        return;
    }

    sub = s.substring(index, index + 2);
    list.add(sub);
    helper(list, s, index + 2);

    if (list.size() == 0) {
        return;
    }

    sub = s.substring(index, index + 3);
    list.add(sub);
    helper(list, s, index + 3);
