import java.util.Arrays;

public class LongestLine {
    public static int longestLine(int[][] mat) {
        int left = 0;
        int top = 0;
        int right = mat[0].length - 1;
        int bottom = mat.length - 1;

        return Math.max(Math.max(horizontalLength(mat, top, right), verticalLength(mat, left, bottom)),
                Math.max(diagonalLength(mat, top, right), antidiagonalLength(mat, top, right)));
    }

    private static int horizontalLength(int[][] mat, int start, int end) {
        if (start >= end) return 0;
        if (mat[start][start] == 0) return 0;

        int max = 1;
        for (int i = start + 1; i <= end; i++) {
            if (mat[start][i] == 0) break;
            max++;
        }
        return max;
    }

    private static int verticalLength(int[][] mat, int start, int end) {
        if (start >= end) return 0;
        if (mat[start][start] == 0) return 0;

        int max = 1;
        for (int i = start + 1; i <= end; i++) {
            if (mat[i][start] == 0) break;
            max++;
        }
        return max;
    }

    private static int diagonalLength(int[][] mat, int start, int end) {
        if (start == end) return 0;
        if (mat[start][start] == 0) return 0;

        int max = 1;
        for (int i = start + 1; i <= end; i++) {
            if (mat[i][i] == 0) break;
            max++;
        }
        return max;
    }

    private static int antidiagonalLength(int[][] mat, int start, int end) {
        if (start == end) return 0;
        if (mat[start][start] == 0) return 0;

        int max = 1;
        for (int i = start + 1, j = end; i <= end && j >= start; i++, j--) {
            if (mat[i][j] == 0) break;
            max++;
        }
        return max;
    }
}
