public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    } else {
        helper(0, result, n);
        return result;
    }
}

private static void helper(int prefix, List<Integer> result, int n) {
    int num = prefix * 10;
    for (int i = 0; i < 10 && num + i <= n; i++) {
        // Append current prefix and number to result list
        result.add(prefix * 10 + i);
        // Helper function call for the next number
        helper(prefix * 10 + i, result, n);
    }
}
